Buildings.constants:
package Medium = {{ library.medium.air | safe }} "Medium model";
package MediumW = {{ library.medium.water | safe }} "Medium model";
{% include 'hydronic_constants.jinja2' %}

templates.construction:
parameter Buildings.HeatTransfer.Data.OpaqueConstructions.Generic
    {{ construction.name }}(
final nLay={{ construction.layers|length }},
absIR_a={{ construction.layers[0].material.longwave_emissivity }},
absIR_b={{ construction.layers[-1].material.longwave_emissivity }},
absSol_a={{ construction.layers[0].material.shortwave_emissivity }},
absSol_b={{ construction.layers[-1].material.shortwave_emissivity }},
material={
{%- for layer in construction.layers -%}
    Buildings.HeatTransfer.Data.Solids.Generic(
    x={{ layer.thickness }},
    k={{ layer.material.thermal_conductivity }},
    c={{ layer.material.specific_heat_capacity }},
    d={{ layer.material.density }}){{ "," if not loop.last }}
{%- endfor %}
},
roughness_a=Buildings.HeatTransfer.Types.SurfaceRoughness.Rough)
annotation (Placement(transformation(extent={% raw %}{{20,84},{34,98}}{% endraw %})));

templates.glazing:
{% set glass_layers =    construction.layers |
    selectattr('layer_type', 'eq', "glass") | list %}
{% set gas_layers =    construction.layers | selectattr('layer_type', 'eq', "gas") | list %}
parameter Buildings.HeatTransfer.Data.GlazingSystems.Generic {{ construction.name }}(
final glass={
{% for layer in glass_layers %}
    Buildings.HeatTransfer.Data.Glasses.Generic(
    x={{ layer.thickness }},
    k={{ layer.material.thermal_conductivity }},
    tauSol={{ macros.join_list(layer.material.solar_transmittance ) }},
    rhoSol_a={{ macros.join_list(layer.material.solar_reflectance_outside_facing ) }},
    rhoSol_b={{ macros.join_list(layer.material.solar_reflectance_room_facing ) }},
    tauIR={{ layer.material.infrared_transmissivity }},
    absIR_a={{ layer.material.infrared_absorptivity_outside_facing }},
    absIR_b={{ layer.material.infrared_absorptivity_room_facing }})
    {{ "," if not loop.last }}
{% endfor %}
},
{% if gas_layers | length > 0 %}
final gas={
{% for layer in gas_layers %}
    {% if layer.layer_type == 'gas' %}
        Buildings.HeatTransfer.Data.Gases.Generic(
        x={{ layer.thickness }},
        a_k={{ layer.material.thermal_conductivity }},
        b_k=0,
        a_mu={{ layer.material.viscosity_coefficients[0] }},
        b_mu={{ layer.material.viscosity_coefficients[1] }},
        a_c={{ layer.material.specific_heat_capacity }},
        b_c=0,
        MM={{ layer.material.molar_mass }})
        {{ "," if not loop.last }}
    {% endif %}
{% endfor %}
},
{% endif %}
UFra={{ construction.u_value_frame }})
annotation (
defaultComponentPrefixes="parameter",
defaultComponentName="datGlaSys");

templates.main:
{% for g in glazing %}
    {{ g|safe }}
{% endfor %}
{%- for c in construction -%}
    {{ c|safe}}
{%- endfor %}

IDEAS.constants:
replaceable package Medium = {{ library.medium.air | safe }}
constrainedby Modelica.Media.Interfaces.PartialMedium
"Medium in the component"
annotation (choicesAllMatching = true);
package MediumW = {{ library.medium.water | safe }} "Medium model";
{% include 'hydronic_constants.jinja2' %}

templates.construction:
      record {{ construction.name }}
    "{{ construction.name }}"
   extends IDEAS.Buildings.Data.Interfaces.Construction(
{#      incLastLay = IDEAS.Types.Tilt.Wall,#}
      mats={
        {%- for layer in construction.layers -%}
        {{ package_name }}.Data.Materials.{{ layer.material.name }}
        (d={{ layer.thickness }}){{ "," if not loop.last }}
        {%- endfor %}
    });
    end {{ construction.name }};

templates.glazing:
{% set glazing = construction.properties %}
record {{ construction.name }} = IDEAS.Buildings.Data.Interfaces.Glazing (
      final nLay={{ construction.layers|length }},
      final checkLowPerformanceGlazing=false,
      mats={
        {%- for layer in construction.layers -%}
        {{ package_name }}.Data.Materials.{{ layer.material.name }}
        (d={{ layer.thickness }}){{ "," if not loop.last }}
        {%- endfor %}
      },
      final SwTrans=[
        {%- for row in glazing.transmittance_table -%}
        {{ row | join(", ") }}{{ ";\n                    " if not loop.last }}
        {%- endfor -%}
      ],
      final SwAbs=[
        {%- for row in glazing.absorptance_table -%}
        {{ row | join(", ") }}{{ ";\n                  " if not loop.last }}
        {%- endfor -%}
      ],
      final SwTransDif={{ glazing.hemispherical_transmittance }},
      final SwAbsDif={ {{- glazing.hemispherical_absorptances | join(", ") -}} },
      final U_value={{ glazing.u_value | round(4) }},
      final g_value={{ glazing.g_value | round(4) }}
    ) "{{ package_name }}";

templates.main:
package Data "Data for transient thermal building simulation"
extends Modelica.Icons.MaterialPropertiesPackage;

package Glazing "Library of building glazing systems"
extends Modelica.Icons.MaterialPropertiesPackage;
{% for g in glazing %}
    {{ g|safe }}
{% endfor %}
end Glazing;

package Materials "Library of construction materials"
extends Modelica.Icons.MaterialPropertiesPackage;
{%- for m in material -%}
    {{ m|safe }}
{%- endfor %}
end Materials;
package Constructions "Library of building envelope constructions"
{%- for c in construction -%}
    {{ c|safe}}
{%- endfor %}

end Constructions;
end Data;
